mapper.select:
SELECT ACM.* FROM `AI_CHAT_MESSAGE` ACM WHERE ACM.DELETED = 0
AND ACM.ENV_CODE = #{req.envCode}
AND ACM.MEMORY_KEY = #{req.memoryKey}
AND ACM.ROLE = #{req.role}
ORDER BY ACM.CREATE_TIME DESC

SELECT ACM.*, FIRST_MSG.CONTENT AS content FROM ( SELECT MEMORY_KEY, MAX(CREATE_TIME) AS MAX_CREATE_TIME, MAX(UPDATE_TIME) AS MAX_UPDATE_TIME FROM `AI_CHAT_MESSAGE` WHERE DELETED = 0
AND ENV_CODE = #{req.envCode}
AND MEMORY_KEY = #{req.memoryKey}
GROUP BY MEMORY_KEY ) GROUP_INFO LEFT JOIN `AI_CHAT_MESSAGE` ACM ON ACM.MEMORY_KEY = GROUP_INFO.MEMORY_KEY AND ACM.UPDATE_TIME = GROUP_INFO.MAX_UPDATE_TIME LEFT JOIN ( SELECT MEMORY_KEY, CONTENT FROM ( SELECT MEMORY_KEY, CONTENT, ROW_NUMBER() OVER (PARTITION BY MEMORY_KEY ORDER BY MESSAGE_ORDER ASC) AS RN FROM `AI_CHAT_MESSAGE` WHERE DELETED = 0
AND ENV_CODE = #{req.envCode}
AND MEMORY_KEY = #{req.memoryKey}
) T WHERE T.RN = 1 ) FIRST_MSG ON FIRST_MSG.MEMORY_KEY = GROUP_INFO.MEMORY_KEY ORDER BY GROUP_INFO.MAX_CREATE_TIME DESC
